 private string$authorizations;private string$transitions;private string$bindings;private string$custody;private string$executions;
 public function __construct(#[Autowire('%kernel.project_dir%')]string$root,private OperationalExecutionCognitionGateway$cognition){$this->authorizations=$root.'/var/imperium/offices/curia/bounded-execution-authorizations';$this->transitions=$root.'/var/imperium/offices/garrison/operational-custody-transitions';$this->bindings=$root.'/var/imperium/mission/occupancy';$this->custody=$root.'/var/imperium/offices/garrison/custody';$this->executions=$root.'/var/imperium/mission/bounded-executions';}
 public function execute(string$authorizationId):array
 {
